<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.sbusage-card')})
watch([dataset,state],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const labels=['Operations','People','Rent','Utilities','Coaches','Support'],colors=['#6366f1','#0d9488','#818cf8','#4f46e5','#14b8a6','#0f766e']
const leaves=computed(()=>dataset.value==='A'?[35,25,30,10]:dataset.value==='B'?[20,20,40,120]:dataset.value==='single'?[0,100,0,0]:[0,0,0,0])
const total=computed(()=>leaves.value.reduce((a,b)=>a+b,0))
const values=computed(()=>[leaves.value[0]+leaves.value[1],leaves.value[2]+leaves.value[3],...leaves.value])
const nodes=computed(()=>values.value.map((value,i)=>{const parent=i<2?total.value:values.value[i<4?0:1],before=i===0||i===2?0:i===1?values.value[0]:leaves.value.slice(0,i-2).reduce((a,b)=>a+b,0);return{value,parent,start:total.value?before/total.value*360:0,end:total.value?(before+value)/total.value*360:0,inner:i<2?26:57,outer:i<2?53:84}}))
function sector(n:{start:number;end:number;inner:number;outer:number}){const pt=(r:number,d:number)=>[160+r*Math.cos((d-90)*Math.PI/180),95+r*Math.sin((d-90)*Math.PI/180)],a=pt(n.outer,n.start),b=pt(n.outer,n.end),c=pt(n.inner,n.end),d=pt(n.inner,n.start);if(n.end-n.start===360){const om=pt(n.outer,n.start+180),im=pt(n.inner,n.start+180);return `M${a} A${n.outer},${n.outer} 0 0 1 ${om} A${n.outer},${n.outer} 0 0 1 ${a} L${d} A${n.inner},${n.inner} 0 0 0 ${im} A${n.inner},${n.inner} 0 0 0 ${d} Z`}const large=n.end-n.start>180?1:0;return `M${a} A${n.outer},${n.outer} 0 ${large} 1 ${b} L${c} A${n.inner},${n.inner} 0 ${large} 0 ${d} Z`}
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section ref="root" class="sbusage-demo" aria-label="Local sunburst chart example"><p>Synthetic expense units. Inner ring: Operations/People. Outer ring: Rent/Utilities within Operations; Coaches/Support within People. Read angle, not area across different radii. Never add parent totals to their leaves.</p><div class="sbusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="single">One nonzero leaf</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="sbusage-card"><template v-if="state==='ready'"><p>Total: {{ total }} units, summed from leaves only.</p><svg viewBox="0 0 320 220" role="img" aria-label="Two hierarchy depths. Top start clockwise; each child stays within its parent's angular interval. Exact values below."><template v-if="total"><path v-for="(n,i) in nodes.filter(n=>n.value>0)" :key="i" :d="sector(n)" :fill="colors[nodes.indexOf(n)]" class="sbusage-sector" :class="{selected:selected===nodes.indexOf(n)}" :data-index="nodes.indexOf(n)" data-cm="fade"/></template><template v-else><circle class="sbusage-track" cx="160" cy="95" r="39.5"/><circle class="sbusage-track" cx="160" cy="95" r="70.5"/></template><text x="160" y="94" text-anchor="middle">{{ total }}</text><text x="160" y="107" text-anchor="middle">units</text><text x="160" y="204" text-anchor="middle">{{ total?'Angle = share of whole · depth = hierarchy':'No positive total: no sectors, undefined shares' }}</text></svg><div role="group" aria-label="Select node" class="sbusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i"><span :style="{background:colors[i]}" aria-hidden="true"></span>{{ label }}</button></div><p role="status">{{ labels[selected] }}: {{ values[selected] }} units; {{ total?(100*values[selected]/total).toFixed(1)+'% of whole':'whole share undefined' }}; {{ nodes[selected].parent?(100*values[selected]/nodes[selected].parent).toFixed(1)+'% of parent':'parent share undefined' }}.</p><table class="sbusage-data"><caption>Exact node units and shares, dataset {{ dataset }}. Parent rows overlap their leaves.</caption><thead><tr><th scope="col">Node</th><th scope="col">Units</th><th scope="col">Whole</th><th scope="col">Parent</th></tr></thead><tbody><tr v-for="(n,i) in nodes" :key="i"><th scope="row">{{ labels[i] }}</th><td>{{ n.value }}</td><td>{{ total?(100*n.value/total).toFixed(1)+'%':'N/A' }}</td><td>{{ n.parent?(100*n.value/n.parent).toFixed(1)+'%':'N/A' }}</td></tr></tbody></table><p class="sbusage-key">Parent of Operations/People is the whole. Rent/Utilities → Operations; Coaches/Support → People. N/A means undefined. Selection never changes the denominator or drills down.</p></template><p v-else role="status" class="sbusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values and sectors are withheld.':'No expense records in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>


.sbusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.sbusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.sbusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.sbusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.sbusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.sbusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.sbusage-demo svg{display:block;width:100%;height:auto;max-height:320px;margin:16px 0}.sbusage-demo svg text{fill:var(--vp-c-text-2);font-size:11px}.sbusage-demo .sbusage-total{fill:var(--vp-c-text-1);font-size:24px;font-weight:700}.sbusage-choices{display:flex;gap:6px;flex-wrap:wrap}.sbusage-choices button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.sbusage-choices span{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}.sbusage-data{display:table!important;width:100%;font-size:12px}.sbusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.sbusage-data :is(td,th){padding:6px!important}.sbusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}

.sbusage-track{fill:none;stroke:var(--vp-c-divider);stroke-width:24}.sbusage-sector{stroke:var(--vp-c-bg);stroke-width:1;opacity:.7}.sbusage-sector.selected{opacity:1;stroke:var(--vp-c-text-1);stroke-width:2}.sbusage-key{font-size:12px;color:var(--vp-c-text-2)}
</style>
